 "content": "def transform(grid):
    """Extend colored crosses along their full rows/columns.

    A neutral (center-zero) cross reserves its center column as a gap in
    horizontal beams. Original 3 markers and colored centers remain intact.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colored, neutral = [], []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if (grid[r-1][c] == grid[r+1][c] ==
                    grid[r][c-1] == grid[r][c+1] == 3):
                if color == 0:
                    neutral.append((r, c))
                elif color != 3:
                    colored.append((r, c, color))
    # All horizontal beams first, then vertical beams so vertical wins at
    # crossings. The empty centers of neutral crosses retain a blank column.
    neutral_cols = {c for r, c in neutral}
    for r, c, color in colored:
        for cc in range(w):
            if grid[r][cc] == 0 and cc not in neutral_cols:
                out[r][cc] = color
    for r, c, color in colored:
        for rr in range(h):
            if grid[rr][c] == 0:
                out[rr][c] = color
    return out

