                color = grid[r][c]
                if color == 0:
                    neutrals.append((r, c))
                elif color != 3:
                    centers.append((r, c, color))

    neutral_centers = set(neutrals)
    colored_centers = {(r, c) for r, c, _ in centers}
    out = [row[:] for row in grid]
    # Horizontal rays are laid first; vertical rays win at overlaps.
    for r, c, color in centers:
        for direction in (-1, 1):
            cc = c + direction
            while 0 <= cc < w:
                if grid[r][cc] != 0:
                    if grid[r][cc] == 3:
                        cc += direction
                        continue
                    break
                if (r, cc) in neutral_centers or (r, cc) in colored_centers:
                    break
                out[r][cc] = color
                cc += direction
    for r, c, color in centers:
        for direction in (-1, 1):
            rr = r + direction
            while 0 <= rr < h:
                if grid[rr][c] != 0:
                    if grid[rr][c] == 3:
                        rr += direction
                        continue
                    break
                if (rr, c) in neutral_centers or (rr, c) in colored_centers:
                    break
                out[rr][c] = color
                rr += direction
