 "content": "def transform(grid):
    """Extend each colored plus along rays, passing its own arms only."""
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if (color not in (0, 3)
                    and grid[r - 1][c] == 3 and grid[r + 1][c] == 3
                    and grid[r][c - 1] == 3 and grid[r][c + 1] == 3):
                centers.append((r, c, color))

    out = [row[:] for row in grid]

    def cast(r, c, color, dr, dc):
        rr, cc = r + dr, c + dc
        own_arms = {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] != 0:
                if (rr, cc) in own_arms and grid[rr][cc] == 3:
                    rr += dr
                    cc += dc
                    continue
                break
            out[rr][cc] = color
            rr += dr
            cc += dc

    # Horizontal rays first; vertical rays overwrite at open crossings.
    for r, c, color in centers:
        cast(r, c, color, 0, -1)
        cast(r, c, color, 0, 1)
    for r, c, color in centers:
        cast(r, c, color, -1, 0)
        cast(r, c, color, 1, 0)
    return out

