                    and grid[r][c - 1] == 3 and grid[r][c + 1] == 3):
                centers.append((r, c, color))

    out = [row[:] for row in grid]

    def cast(r, c, color, dr, dc):
        own_arms = {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
